function classNames(...classes: Array<string | false | null | undefined>) { return classes.filter(Boolean).join(" "); }
function formatBytes(bytes: number) { if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`; return `${(bytes / (1024 * 1024)).toFixed(1)} MB`; }
function dateKey(date: Date) { return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
function humanDate(value: string) { return new Intl.DateTimeFormat("es-VE", { day: "numeric", month: "short" }).format(new Date(`${value}T12:00:00`)); }

function Badge({ children, tone = "slate" }: { children: React.ReactNode; tone?: "red" | "blue" | "green" | "orange" | "purple" | "slate" }) {
  const tones = { red: "border-[#74303b] bg-[#35171f] text-[#ff8994]", blue: "border-[#24528f] bg-[#102640] text-[#73b2ff]", green: "border-[#466b2b] bg-[#172817] text-[#b9ff78]", orange: "border-[#714521] bg-[#301d11] text-[#ffad69]", purple: "border-[#51327b] bg-[#241633] text-[#d2a8ff]", slate: "border-[#2c3b4f] bg-[#17202c] text-[#aab8c8]" };
  return <span className={classNames("inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.12em]", tones[tone])}>{children}</span>;
}
function SectionHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><div className="eyebrow mb-2">{eyebrow}</div><h1 className="font-display text-4xl font-bold uppercase leading-none tracking-tight text-white md:text-5xl">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-[#93a1b2]">{description}</p></div>{action}</div>; }
function IconButton({ label, children, onClick }: { label: string; children: React.ReactNode; onClick?: () => void }) { return <button aria-label={label} title={label} onClick={onClick} className="focus-ring flex h-9 w-9 items-center justify-center rounded-lg border border-[#26364b] bg-[#0f1721] text-[#96a5b8] transition hover:border-[#526b8a] hover:text-white">{children}</button>; }

function Overview({ setSection, players, content, notifications, customNotifications, discordData, onSendNotice, onAddCustomNotification, onMarkNotificationRead, onDismissNotification, onEnableAlerts }: { setSection: (section: Section) => void; players: Player[]; content: ContentItem[]; notifications: NotificationItem[]; customNotifications: CustomNotification[]; discordData: DiscordWidgetData | null; onSendNotice: (message: string) => Promise<void>; onAddCustomNotification: (title: string, detail: string, severity: CustomNotification["severity"]) => void; onMarkNotificationRead: (id: number) => void; onDismissNotification: (id: number) => void; onEnableAlerts: () => Promise<void> }) {
  const activePlayers = players.filter((player) => player.status === "Activo").length;
  return <>
    <div className="panel scanline data-grid relative overflow-hidden p-6 md:p-8"><div className="relative z-10 flex flex-col justify-between gap-8 lg:flex-row lg:items-end"><div className="max-w-2xl"><div className="mb-5 flex items-center gap-2"><Badge tone="red"><Radio className="h-3 w-3" /> Operación activa</Badge><span className="text-[11px] uppercase tracking-[.16em] text-[#718096]">Semana 01 · preparación competitiva</span></div><h1 className="font-display text-5xl font-bold uppercase leading-[.87] tracking-tight text-white md:text-7xl">Sube el nivel.<br /><span className="text-[#e6293f]">Compite con propósito.</span></h1><p className="mt-6 max-w-xl text-sm leading-6 text-[#a6b2c1]">CROSAIM conecta operación competitiva, publicaciones tácticas, clips y seguimiento del equipo. Cada área deja una acción clara para el siguiente entrenamiento.</p></div><div className="min-w-[230px] border-l border-[#29374a] pl-5 lg:mb-1"><div className="eyebrow mb-3">Objetivo de esta semana</div><div className="flex items-end justify-between"><span className="font-display text-4xl font-bold text-white">68%</span><span className="mb-1 text-xs text-[#8494a8]">17 / 25 acciones</span></div><div className="progress-track mt-3"><div className="progress-fill" style={{ width: "68%" }} /></div><p className="mt-3 text-xs leading-5 text-[#8e9daf]">Cerrar roster inicial, preparar 2 guías y dejar listo el registro TPG Maracay.</p></div></div></div>
    <div className="mt-4 grid grid-cols-2 gap-3 lg:grid-cols-4">{[{ label: "Jugadores activos", value: `${activePlayers}/5`, meta: "+1 en tryout", icon: Users, tone: "#e6293f", action: () => setSection("roster") }, { label: "Próximo torneo", value: "18 días", meta: "TPG · Maracay", icon: Trophy, tone: "#ff7a18", action: () => setSection("tournaments") }, { label: "Contenido en cola", value: `${content.filter((item) => item.status !== "Publicado").length}`, meta: "2 plataformas", icon: Video, tone: "#1677ff", action: () => setSection("content") }, { label: "Avisos pendientes", value: (notifications.length + customNotifications.filter((item) => !item.read).length).toString(), meta: "Discord live", icon: Bell, tone: "#9b3dff", action: () => document.getElementById("discord-live-panel")?.scrollIntoView({ behavior: "smooth" }) }].map((item) => <button key={item.label} onClick={item.action} className="panel panel-hover group p-4 text-left"><div className="mb-5 flex items-center justify-between"><span className="eyebrow">{item.label}</span><item.icon className="h-4 w-4" style={{ color: item.tone }} /></div><div className="font-display text-3xl font-bold tracking-tight text-white">{item.value}</div><div className="mt-1 text-xs text-[#8291a4]">{item.meta}</div><ChevronRight className="mt-4 h-4 w-4 text-[#3d4c60] transition group-hover:translate-x-1 group-hover:text-white" /></button>)}</div>
    <div className="mt-4 grid gap-4 xl:grid-cols-[1.3fr_.7fr]"><div className="panel p-5 md:p-6"><div className="mb-6 flex items-center justify-between"><div><div className="eyebrow mb-2">Pipeline de contenido</div><h2 className="font-display text-2xl font-bold uppercase text-white">Lo que sale esta semana</h2></div><button onClick={() => setSection("content")} className="focus-ring text-xs font-bold uppercase tracking-[.12em] text-[#e6293f] hover:text-white">Ver tablero <ArrowUpRight className="ml-1 inline h-3.5 w-3.5" /></button></div><div className="space-y-3">{content.map((item) => <ContentRow key={item.id} item={item} compact />)}</div></div><div className="panel p-5 md:p-6"><div className="eyebrow mb-2">Próximos hitos</div><h2 className="font-display text-2xl font-bold uppercase text-white">Calendario TPG</h2><div className="mt-6 space-y-1">{tournamentData.map((item, index) => <TournamentRow key={item.name} item={item} first={index === 0} />)}</div><button onClick={() => setSection("tournaments")} className="focus-ring mt-5 flex w-full items-center justify-center gap-2 border-t border-[#202e40] pt-4 text-xs font-bold uppercase tracking-[.12em] text-[#a7b6c7] transition hover:text-white">Gestionar participación <ChevronRight className="h-4 w-4" /></button></div></div>
    <div className="mt-4 grid gap-4 lg:grid-cols-[.8fr_1.2fr]"><div className="panel p-5 md:p-6"><div className="eyebrow mb-2">Acción rápida</div><h2 className="font-display text-2xl font-bold uppercase text-white">Programa el próximo clip</h2><p className="mt-3 text-sm leading-6 text-[#8e9daf]">Sube el video, escribe el contexto táctico y colócalo en el calendario editorial para no perder el ritmo de publicación.</p><div className="mt-6 flex flex-wrap gap-2"><button onClick={() => setSection("calendar")} className="focus-ring inline-flex items-center gap-2 rounded-lg bg-[#1677ff] px-4 py-3 text-xs font-bold uppercase tracking-[.1em] text-white hover:bg-[#2e87ff]"><CalendarPlus className="h-4 w-4" /> Abrir calendario</button><button onClick={() => void onEnableAlerts()} className="focus-ring inline-flex items-center gap-2 rounded-lg border border-[#51327b] bg-[#241633] px-4 py-3 text-xs font-bold uppercase tracking-[.1em] text-[#d2a8ff] hover:bg-[#302044]"><Bell className="h-4 w-4" /> Activar alertas</button></div></div><DiscordPanel notifications={notifications} customNotifications={customNotifications} discordData={discordData} onSendNotice={onSendNotice} onAddCustomNotification={onAddCustomNotification} onMarkNotificationRead={onMarkNotificationRead} onDismissNotification={onDismissNotification} /></div>
  </>;
}

function DiscordPanel({ notifications, customNotifications, discordData, onSendNotice, onAddCustomNotification, onMarkNotificationRead, onDismissNotification }: { notifications: NotificationItem[]; customNotifications: CustomNotification[]; discordData: DiscordWidgetData | null; onSendNotice: (message: string) => Promise<void>; onAddCustomNotification: (title: string, detail: string, severity: CustomNotification["severity"]) => void; onMarkNotificationRead: (id: number) => void; onDismissNotification: (id: number) => void }) {
  const [message, setMessage] = useState("");
  const [sending, setSending] = useState(false);
  const [showComposer, setShowComposer] = useState(false);
  const [title, setTitle] = useState("");
  const [detail, setDetail] = useState("");
  const [severity, setSeverity] = useState<CustomNotification["severity"]>("info");
  const submitNotice = async () => { if (!message.trim()) return; setSending(true); await onSendNotice(message.trim()); setMessage(""); setSending(false); };
  const submitCustom = () => { if (!title.trim() || !detail.trim()) return; onAddCustomNotification(title.trim(), detail.trim(), severity); setTitle(""); setDetail(""); setSeverity("info"); setShowComposer(false); };
  const unread = customNotifications.filter((item) => !item.read).length;
  const statusTone = (status: string) => status === "online" ? "bg-[#a8ff2a]" : status === "dnd" ? "bg-[#e6293f]" : "bg-[#ffad69]";
  return <div id="discord-live-panel" className="panel overflow-hidden"><div className="flex flex-col justify-between gap-3 border-b border-[#202e40] px-5 py-4 sm:flex-row sm:items-center"><div><div className="eyebrow mb-2">Discord · canal operativo</div><h2 className="font-display text-2xl font-bold uppercase text-white">Avisos personalizados</h2><p className="mt-1 text-xs text-[#8190a3]">{discordData?.name ?? "CA CROSAIM"} · {discordData?.presenceCount ?? "—"} presentes</p></div><div className="flex items-center gap-2"><Badge tone="green"><span className="h-1.5 w-1.5 rounded-full bg-[#b9ff78]" /> {discordData ? "Datos actualizados" : "Conectando"}</Badge>{unread > 0 && <Badge tone="purple">{unread} nuevas</Badge>}</div></div><div className="grid gap-4 p-4 md:grid-cols-[350px_1fr]"><div><iframe title="Servidor Discord CROSAIM" src={discordWidgetUrl} width="350" height="220" allowTransparency frameBorder="0" sandbox="allow-popups allow-popups-to-escape-sandbox allow-same-origin allow-scripts" className="h-[220px] w-full max-w-[350px] rounded-xl border border-[#26384e] bg-[#0d141e]" />{discordData?.instantInvite && <a href={discordData.instantInvite} target="_blank" rel="noreferrer" className="focus-ring mt-2 flex items-center justify-center gap-2 rounded-lg border border-[#51327b] bg-[#241633] px-3 py-2 text-[10px] font-bold uppercase tracking-[.1em] text-[#d2a8ff] hover:bg-[#302044]">Unirse a {discordData.name} <ExternalLink className="h-3.5 w-3.5" /></a>}</div><div className="min-w-0"><div className="mb-3 flex items-center justify-between"><span className="eyebrow">Actividad y avisos</span><button onClick={() => setShowComposer((value) => !value)} className="focus-ring inline-flex items-center gap-1.5 rounded-md border border-[#2b3b50] px-2.5 py-1.5 text-[10px] font-bold uppercase tracking-[.08em] text-[#aebccc] hover:text-white"><Plus className="h-3 w-3" /> Crear aviso</button></div><div className="max-h-[190px] space-y-2 overflow-y-auto pr-1">{customNotifications.map((item) => <div key={item.id} className={classNames("flex gap-2 rounded-lg border p-2.5", item.read ? "border-[#1e2b3b] bg-[#0b121a] opacity-65" : "border-[#51327b] bg-[#120e1a]")}><span className={classNames("mt-1 h-2 w-2 shrink-0 rounded-full", item.severity === "urgent" ? "bg-[#e6293f]" : item.severity === "warning" ? "bg-[#ff7a18]" : item.severity === "success" ? "bg-[#a8ff2a]" : "bg-[#1677ff]")} /><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold text-white">{item.title}</div><div className="truncate text-[11px] text-[#8291a4]">{item.detail}</div><div className="mt-1 text-[9px] uppercase tracking-[.08em] text-[#66778d]">{item.time} · {item.severity}</div></div><div className="flex shrink-0 gap-1"><button onClick={() => onMarkNotificationRead(item.id)} className="focus-ring rounded p-1 text-[#71849a] hover:text-white" aria-label={item.read ? "Marcar como no leído" : "Marcar como leído"}><Check className="h-3.5 w-3.5" /></button><button onClick={() => onDismissNotification(item.id)} className="focus-ring rounded p-1 text-[#71849a] hover:text-[#ff8994]" aria-label="Descartar aviso"><X className="h-3.5 w-3.5" /></button></div></div>)}{notifications.map((item) => <div key={`discord-${item.id}`} className="flex gap-2 rounded-lg border border-[#223246] bg-[#0d141e] p-2.5"><span className={classNames("mt-1 h-2 w-2 shrink-0 rounded-full", item.tone === "purple" ? "bg-[#9b3dff]" : item.tone === "orange" ? "bg-[#ff7a18]" : item.tone === "green" ? "bg-[#a8ff2a]" : "bg-[#1677ff]")} /><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold text-white">{item.title}</div><div className="truncate text-[11px] text-[#8291a4]">{item.detail}</div></div><span className="whitespace-nowrap text-[9px] text-[#66778d]">{item.time}</span></div>)}</div>{showComposer && <div className="mt-3 rounded-xl border border-[#2b3b50] bg-[#0b121a] p-3"><div className="mb-2 text-[10px] font-bold uppercase tracking-[.1em] text-[#aebccc]">Nuevo aviso personalizado</div><div className="grid gap-2 sm:grid-cols-2"><input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Título" className="focus-ring rounded-lg border border-[#2b3b50] bg-[#080d13] px-3 py-2 text-xs text-white placeholder:text-[#647489]" /><select value={severity} onChange={(event) => setSeverity(event.target.value as CustomNotification["severity"])} className="focus-ring rounded-lg border border-[#2b3b50] bg-[#080d13] px-3 py-2 text-xs text-white"><option value="info">Informativo</option><option value="success">Éxito</option><option value="warning">Atención</option><option value="urgent">Urgente</option></select></div><textarea value={detail} onChange={(event) => setDetail(event.target.value)} placeholder="Mensaje, instrucción o recordatorio..." rows={2} className="focus-ring mt-2 w-full resize-none rounded-lg border border-[#2b3b50] bg-[#080d13] px-3 py-2 text-xs text-white placeholder:text-[#647489]" /><button onClick={submitCustom} className="focus-ring mt-2 rounded-lg bg-[#9b3dff] px-3 py-2 text-[10px] font-bold uppercase tracking-[.1em] text-white hover:bg-[#ad5bff]">Guardar aviso</button></div>}<div className="mt-3 flex gap-2"><input value={message} onChange={(event) => setMessage(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") void submitNotice(); }} placeholder="Enviar aviso al equipo por Discord..." className="focus-ring min-w-0 flex-1 rounded-lg border border-[#2b3b50] bg-[#0a1018] px-3 py-2 text-xs text-white placeholder:text-[#647489]" /><button onClick={() => void submitNotice()} disabled={sending || !message.trim()} className="focus-ring flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#e6293f] text-white disabled:cursor-not-allowed disabled:opacity-40"><Send className="h-4 w-4" /></button></div></div></div><div className="border-t border-[#202e40] px-5 py-3 text-[10px] leading-5 text-[#74859a]">Con la cuenta conectada, los avisos se guardan en la base de datos y se sincronizan entre dispositivos; sin cuenta quedan solo en este navegador. El widget usa datos públicos de Discord y las postulaciones automáticas todavía requieren un bot o bridge.</div></div>;
}
function ContentRow({ item, compact = false }: { item: ContentItem; compact?: boolean }) { const statusTone = item.status === "Publicado" ? "green" : item.status === "Listo para publicar" ? "blue" : "slate"; return <div className={classNames("group flex items-center gap-3 rounded-xl border border-[#1e2c3d] bg-[#0d141e] p-3 transition hover:border-[#344a66]", !compact && "p-4")}><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg" style={{ color: item.accent, backgroundColor: `${item.accent}18` }}>{item.platform === "Tracker.gg" ? <Target className="h-4 w-4" /> : item.platform === "Discord" ? <Users className="h-4 w-4" /> : <Video className="h-4 w-4" />}</span><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold text-white">{item.title}</div><div className="mt-1 truncate text-xs text-[#7f8ea1]">{item.type} · {item.platform}</div></div><Badge tone={statusTone}>{item.status}</Badge><ChevronRight className="hidden h-4 w-4 text-[#53647a] sm:block" /></div>; }
function TournamentRow({ item, first = false }: { item: typeof tournamentData[number]; first?: boolean }) { return <div className="group flex gap-3 border-b border-[#1c2938] py-4 last:border-0"><div className="mt-1 h-2 w-2 shrink-0 rounded-full" style={{ backgroundColor: item.color, boxShadow: first ? `0 0 0 4px ${item.color}20` : undefined }} /><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-3"><strong className="truncate text-sm text-white">{item.name}</strong><span className="whitespace-nowrap font-display text-sm font-bold text-[#dbe4ed]">{item.date}</span></div><div className="mt-1 truncate text-xs text-[#7f8ea1]">{item.city}</div></div><a href={item.url} target="_blank" rel="noreferrer" aria-label={`Abrir ${item.name}`} className="self-center text-[#708399] hover:text-white"><ExternalLink className="h-3.5 w-3.5" /></a></div>; }

type ApplicationRecord = { id: number; playerName: string; discordUsername: string; discordUserId: string | null; contact: string | null; role: string; rank: string; message: string; status: "Pendiente" | "En revisión" | "Entrevista" | "Aprobada" | "Rechazada"; createdAt: string | Date };

function ApplicationStatusBadge({ status }: { status: ApplicationRecord["status"] }) {
  const tone = status === "Aprobada" ? "green" : status === "Rechazada" ? "red" : status === "Entrevista" ? "purple" : status === "En revisión" ? "blue" : "orange";
  return <Badge tone={tone}>{status}</Badge>;
}

function Roster({ players, setPlayers }: { players: Player[]; setPlayers: React.Dispatch<React.SetStateAction<Player[]>> }) {
  const { user } = useAuth();
  const [showForm, setShowForm] = useState(false);
  const [showApplicationForm, setShowApplicationForm] = useState(false);
  const [newHandle, setNewHandle] = useState("");
  const [newRole, setNewRole] = useState("Flex");
  const [newRank, setNewRank] = useState("Por verificar");
  const [newSource, setNewSource] = useState<PlayerSource>("CROSAIM");
  const [query, setQuery] = useState("");
  const [roleFilter, setRoleFilter] = useState("Todos");
  const [rankFilter, setRankFilter] = useState("Todos");
  const [sourceFilter, setSourceFilter] = useState("Todos");
  const [sortBy, setSortBy] = useState("handle");
  const [applicationForm, setApplicationForm] = useState({ playerName: "", discordUsername: "", discordUserId: "", contact: "", role: "Duelista", rank: "Por verificar", message: "", website: "" });
  const [applicationMessage, setApplicationMessage] = useState("");
  const [lookupParams, setLookupParams] = useState({ id: 0, discordUsername: "" });
  const applicationsQuery = trpc.applications.list.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const lookupApplication = trpc.applications.lookup.useQuery(lookupParams, { enabled: false, retry: false });
  const submitApplication = trpc.applications.submit.useMutation({ onSuccess: (result) => { setApplicationMessage(result.message); setApplicationForm({ playerName: "", discordUsername: "", discordUserId: "", contact: "", role: "Duelista", rank: "Por verificar", message: "", website: "" }); setShowApplicationForm(false); void applicationsQuery.refetch(); } });
  const updateApplication = trpc.applications.updateStatus.useMutation({ onSuccess: () => void applicationsQuery.refetch() });
  const createRosterPlayer = trpc.roster.create.useMutation();
  const roles = ["Todos", ...Array.from(new Set(players.map((player) => player.role)))];
  const ranks = ["Todos", ...Array.from(new Set(players.map((player) => player.rank)))];
  const sources = ["Todos", "Tracker.gg", "TPG", "CROSAIM", "Discord"];
  const filteredPlayers = [...players].filter((player) => { const matchesQuery = `${player.handle} ${player.role} ${player.rank}`.toLowerCase().includes(query.toLowerCase()); return matchesQuery && (roleFilter === "Todos" || player.role === roleFilter) && (rankFilter === "Todos" || player.rank === rankFilter) && (sourceFilter === "Todos" || player.source === sourceFilter); }).sort((a, b) => sortBy === "rank" ? a.rank.localeCompare(b.rank) : sortBy === "role" ? a.role.localeCompare(b.role) : a.handle.localeCompare(b.handle));
  const addPlayer = () => { if (!newHandle.trim()) return; const player = { handle: newHandle.trim().toUpperCase(), role: newRole, rank: newRank, availability: "Por confirmar", status: "Pendiente" as const, source: newSource, color: "#ff7a18" }; setPlayers((current) => [...current, { id: Date.now(), ...player }]); if (user) createRosterPlayer.mutate(player); setNewHandle(""); setShowForm(false); };
  const recruitApplication = (application: ApplicationRecord) => { const player = { handle: application.playerName.toUpperCase(), role: application.role, rank: application.rank, availability: "Por confirmar", status: "Tryout" as const, source: "Discord" as const, color: "#9b3dff" }; setPlayers((current) => current.some((item) => item.handle.toLowerCase() === application.playerName.toLowerCase()) ? current : [...current, { id: Date.now(), ...player }]); if (user) createRosterPlayer.mutate(player); };
  const submitApplicationForm = () => { if (applicationForm.website || applicationForm.playerName.trim().length < 2 || applicationForm.discordUsername.trim().length < 2 || applicationForm.message.trim().length < 10) return; submitApplication.mutate({ ...applicationForm, discordUserId: applicationForm.discordUserId || undefined, contact: applicationForm.contact || undefined }); };
  const checkApplicationStatus = () => { if (lookupParams.id > 0 && lookupParams.discordUsername.trim().length >= 2) void lookupApplication.refetch(); };
  const applications = (applicationsQuery.data ?? []) as ApplicationRecord[];
  return <><SectionHeader eyebrow="Operación · roster" title="Plantilla & tryouts" description="Busca jugadores por alias, rol, rango o procedencia. Las postulaciones conservan el nombre real, Discord y contacto para que puedas verificar y reclutar sin perder el contexto." action={<div className="flex flex-wrap gap-2"><button onClick={() => setShowApplicationForm((value) => !value)} className="focus-ring inline-flex items-center justify-center gap-2 rounded-lg border border-[#9b3dff] bg-[#241633] px-4 py-2.5 text-xs font-bold uppercase tracking-[.12em] text-[#d2a8ff] transition hover:bg-[#302044]"><UserPlus className="h-4 w-4" /> Nueva postulación</button><button onClick={() => setShowForm((value) => !value)} className="focus-ring inline-flex items-center justify-center gap-2 rounded-lg bg-[#e6293f] px-4 py-2.5 text-xs font-bold uppercase tracking-[.12em] text-white transition hover:bg-[#f04153]"><Plus className="h-4 w-4" /> Añadir jugador</button></div>} /><div className="mb-4 grid grid-cols-2 gap-3 md:grid-cols-4"><SmallMetric label="Activos" value={players.filter((player) => player.status === "Activo").length.toString()} note="listos" color="#a8ff2a" /><SmallMetric label="Tryout" value={players.filter((player) => player.status === "Tryout").length.toString()} note="en evaluación" color="#9b3dff" /><SmallMetric label="Postulaciones" value={applications.length.toString()} note="con identidad" color="#ff7a18" /><SmallMetric label="Cupo objetivo" value={`${players.length}/5`} note="plantilla base" color="#1677ff" /></div>{showApplicationForm && <div className="panel mb-4 border-[#51327b] p-5"><div className="mb-4 flex items-start justify-between gap-3"><div><div className="eyebrow mb-2">Identidad verificable</div><h2 className="font-display text-2xl font-bold uppercase text-white">Registrar postulación</h2><p className="mt-1 text-xs leading-5 text-[#9caabd]">El nombre y Discord se incluyen en el aviso que recibe el bot para que el equipo sepa a quién contactar.</p></div><Badge tone="purple">Nombre obligatorio</Badge></div><div className="grid gap-3 md:grid-cols-2"><label><span className="eyebrow mb-2 block text-[#d2a8ff]">Nombre del jugador *</span><input value={applicationForm.playerName} onChange={(event) => setApplicationForm({ ...applicationForm, playerName: event.target.value })} placeholder="Nombre o Riot ID" className="focus-ring w-full rounded-lg border border-[#51327b] bg-[#0b0d14] px-3 py-2.5 text-sm text-white placeholder:text-[#746a82]" /></label><label><span className="eyebrow mb-2 block text-[#d2a8ff]">Usuario de Discord *</span><input value={applicationForm.discordUsername} onChange={(event) => setApplicationForm({ ...applicationForm, discordUsername: event.target.value })} placeholder="usuario o usuario#0000" className="focus-ring w-full rounded-lg border border-[#51327b] bg-[#0b0d14] px-3 py-2.5 text-sm text-white placeholder:text-[#746a82]" /></label><label><span className="eyebrow mb-2 block text-[#d2a8ff]">ID de Discord</span><input value={applicationForm.discordUserId} onChange={(event) => setApplicationForm({ ...applicationForm, discordUserId: event.target.value })} placeholder="Opcional, 18 dígitos" className="focus-ring w-full rounded-lg border border-[#51327b] bg-[#0b0d14] px-3 py-2.5 text-sm text-white placeholder:text-[#746a82]" /></label><label><span className="eyebrow mb-2 block text-[#d2a8ff]">Contacto alterno</span><input value={applicationForm.contact} onChange={(event) => setApplicationForm({ ...applicationForm, contact: event.target.value })} placeholder="Email, WhatsApp u otro" className="focus-ring w-full rounded-lg border border-[#51327b] bg-[#0b0d14] px-3 py-2.5 text-sm text-white placeholder:text-[#746a82]" /></label><label><span className="eyebrow mb-2 block text-[#d2a8ff]">Rol *</span><select value={applicationForm.role} onChange={(event) => setApplicationForm({ ...applicationForm, role: event.target.value })} className="focus-ring w-full rounded-lg border border-[#51327b] bg-[#0b0d14] px-3 py-2.5 text-sm text-white"><option>Duelista</option><option>Iniciador</option><option>Controlador</option><option>Sentinela</option><option>Flex</option><option>IGL</option></select></label><label><span className="eyebrow mb-2 block text-[#d2a8ff]">Rango *</span><select value={applicationForm.rank} onChange={(event) => setApplicationForm({ ...applicationForm, rank: event.target.value })} className="focus-ring w-full rounded-lg border border-[#51327b] bg-[#0b0d14] px-3 py-2.5 text-sm text-white"><option>Por verificar</option><option>Iron</option><option>Bronze</option><option>Silver</option><option>Gold</option><option>Platinum</option><option>Diamond</option><option>Ascendant</option><option>Immortal</option><option>Radiant</option></select></label></div><label aria-hidden="true" className="absolute -left-[10000px] h-px w-px overflow-hidden"><span>Website</span><input tabIndex={-1} autoComplete="off" value={applicationForm.website} onChange={(event) => setApplicationForm({ ...applicationForm, website: event.target.value })} /></label><label className="mt-3 block"><span className="eyebrow mb-2 block text-[#d2a8ff]">Mensaje del jugador *</span><textarea value={applicationForm.message} onChange={(event) => setApplicationForm({ ...applicationForm, message: event.target.value })} rows={3} placeholder="Experiencia, disponibilidad y por qué quieres entrar a CROSAIM..." className="focus-ring w-full resize-none rounded-lg border border-[#51327b] bg-[#0b0d14] px-3 py-2.5 text-sm text-white placeholder:text-[#746a82]" /></label><div className="mt-3 flex flex-wrap items-center gap-3"><button onClick={submitApplicationForm} disabled={submitApplication.isPending} className="focus-ring rounded-lg bg-[#9b3dff] px-4 py-2.5 text-xs font-bold uppercase tracking-[.1em] text-white disabled:opacity-50">{submitApplication.isPending ? "Enviando..." : "Enviar postulación"}</button>{submitApplication.error && <span className="text-xs text-[#ff8994]">{submitApplication.error?.message ?? "No se pudo guardar la postulación. Revisa los datos e inténtalo nuevamente."}</span>}{applicationMessage && <span className="text-xs text-[#b9ff78]">{applicationMessage}</span>}</div></div>}<div className="panel mb-4 border-[#24528f] p-5"><div className="eyebrow mb-2 text-[#73b2ff]">Seguimiento público</div><h2 className="font-display text-2xl font-bold uppercase text-white">Consulta tu postulación</h2><p className="mt-2 text-xs leading-5 text-[#9caabd]">El jugador puede consultar el estado sin iniciar sesión usando el número recibido y su usuario de Discord.</p><div className="mt-4 grid gap-2 md:grid-cols-[180px_1fr_auto]"><input type="number" min="1" value={lookupParams.id || ""} onChange={(event) => setLookupParams({ ...lookupParams, id: Number(event.target.value) || 0 })} placeholder="N.º de postulación" className="focus-ring rounded-lg border border-[#24528f] bg-[#0a1018] px-3 py-2.5 text-sm text-white placeholder:text-[#637287]" /><input value={lookupParams.discordUsername} onChange={(event) => setLookupParams({ ...lookupParams, discordUsername: event.target.value })} placeholder="Usuario de Discord" className="focus-ring rounded-lg border border-[#24528f] bg-[#0a1018] px-3 py-2.5 text-sm text-white placeholder:text-[#637287]" /><button onClick={checkApplicationStatus} disabled={lookupApplication.isFetching} className="focus-ring rounded-lg bg-[#1677ff] px-4 py-2.5 text-xs font-bold uppercase tracking-[.1em] text-white disabled:opacity-50">{lookupApplication.isFetching ? "Consultando..." : "Consultar"}</button></div>{lookupApplication.error && <p className="mt-3 text-xs text-[#ffad69]">{lookupApplication.error.message}</p>}{lookupApplication.data && <div className="mt-4 rounded-lg border border-[#2c4e78] bg-[#102640] p-4 text-sm text-[#dceaff]"><strong>{lookupApplication.data.playerName}</strong> · {lookupApplication.data.role} · {lookupApplication.data.rank}<div className="mt-1 text-xs text-[#73b2ff]">Estado actual: {lookupApplication.data.status}</div></div>}</div>{showForm && <div className="panel mb-4 flex flex-col gap-3 border-[#704523] p-4 md:flex-row md:items-end"><label className="flex-1"><span className="eyebrow mb-2 block text-[#ffad69]">Riot ID / Alias</span><input value={newHandle} onChange={(event) => setNewHandle(event.target.value)} placeholder="Ej. CROSAIM · SENTINEL" className="focus-ring w-full rounded-lg border border-[#704523] bg-[#0a1018] px-3 py-2.5 text-sm text-white placeholder:text-[#637287]" /></label><label className="w-full md:w-44"><span className="eyebrow mb-2 block text-[#ffad69]">Rol</span><select value={newRole} onChange={(event) => setNewRole(event.target.value)} className="focus-ring w-full rounded-lg border border-[#704523] bg-[#0a1018] px-3 py-2.5 text-sm text-white"><option>Flex</option><option>IGL</option><option>Duelista</option><option>Iniciador</option><option>Controlador</option><option>Sentinela</option></select></label><label className="w-full md:w-44"><span className="eyebrow mb-2 block text-[#ffad69]">Rango</span><select value={newRank} onChange={(event) => setNewRank(event.target.value)} className="focus-ring w-full rounded-lg border border-[#704523] bg-[#0a1018] px-3 py-2.5 text-sm text-white"><option>Por verificar</option><option>Iron</option><option>Bronze</option><option>Silver</option><option>Gold</option><option>Platinum</option><option>Diamond</option><option>Ascendant</option><option>Immortal</option><option>Radiant</option></select></label><button onClick={addPlayer} className="focus-ring rounded-lg border border-[#456c30] bg-[#1a3119] px-4 py-2.5 text-xs font-bold uppercase tracking-[.1em] text-[#b9ff78] hover:bg-[#25451f]">Guardar</button></div>}<div className="panel mb-4 p-4"><div className="mb-3 flex items-center gap-2"><SlidersHorizontal className="h-4 w-4 text-[#e6293f]" /><span className="eyebrow">Filtros de plantilla</span><span className="ml-auto text-[10px] uppercase tracking-[.1em] text-[#728399]">{filteredPlayers.length} resultados</span></div><div className="grid gap-2 md:grid-cols-[1.5fr_1fr_1fr_1fr_1fr]"><label className="relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-[#62738a]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar alias, rol o rango..." className="focus-ring w-full rounded-lg border border-[#2c3c50] bg-[#0a1018] py-2.5 pl-9 pr-3 text-sm text-white placeholder:text-[#637287]" /></label><FilterSelect label="Rol" value={roleFilter} options={roles} onChange={setRoleFilter} /><FilterSelect label="Rango" value={rankFilter} options={ranks} onChange={setRankFilter} /><FilterSelect label="Fuente" value={sourceFilter} options={sources} onChange={setSourceFilter} /><label className="relative"><ArrowDownAZ className="absolute left-3 top-2.5 h-4 w-4 text-[#62738a]" /><select value={sortBy} onChange={(event) => setSortBy(event.target.value)} className="focus-ring w-full appearance-none rounded-lg border border-[#2c3c50] bg-[#0a1018] py-2.5 pl-9 pr-3 text-xs text-white"><option value="handle">Ordenar por alias</option><option value="role">Ordenar por rol</option><option value="rank">Ordenar por rango</option></select></label></div></div><div className="panel mb-4 overflow-hidden"><div className="flex items-center justify-between border-b border-[#202e3e] bg-[#101724] px-5 py-4"><div><div className="eyebrow mb-1 text-[#d2a8ff]">Reclutamiento · identidad</div><h2 className="font-display text-2xl font-bold uppercase text-white">Postulaciones recibidas</h2></div><Badge tone="purple">{applications.length} perfiles</Badge></div><div className="divide-y divide-[#1c2938]">{applicationsQuery.isLoading && <div className="p-5 text-sm text-[#9caabd]">Cargando postulaciones...</div>}{applicationsQuery.error && <div className="p-5 text-sm text-[#ffad69]">Conecta la cuenta administradora para ver y gestionar postulaciones.</div>}{!applicationsQuery.isLoading && !applications.length && <div className="p-5 text-sm text-[#9caabd]">Todavía no hay postulaciones guardadas.</div>}{applications.map((application) => <div key={application.id} className="p-5"><div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-start"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="font-display text-xl font-bold text-white">{application.playerName}</span><ApplicationStatusBadge status={application.status} /></div><div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-[#b6c4d3]"><span className="text-[#d2a8ff]">Discord: {application.discordUsername}</span>{application.discordUserId && <span>ID: {application.discordUserId}</span>}{application.contact && <span>Contacto: {application.contact}</span>}</div><div className="mt-3 grid gap-2 text-xs text-[#d2dce7] sm:grid-cols-2"><span><strong className="text-[#ffad69]">Rol:</strong> {application.role}</span><span><strong className="text-[#ffad69]">Rango:</strong> {application.rank}</span></div><p className="mt-3 max-w-3xl text-sm leading-6 text-[#c6d1dd]">{application.message}</p></div><div className="flex flex-wrap gap-2 lg:max-w-[290px] lg:justify-end">{application.status === "Pendiente" && <button onClick={() => updateApplication.mutate({ id: application.id, status: "En revisión" })} className="focus-ring rounded-lg border border-[#24528f] bg-[#102640] px-3 py-2 text-[10px] font-bold uppercase tracking-[.08em] text-[#73b2ff]">Verificar datos</button>}{application.status === "En revisión" && <button onClick={() => updateApplication.mutate({ id: application.id, status: "Entrevista" })} className="focus-ring rounded-lg border border-[#51327b] bg-[#241633] px-3 py-2 text-[10px] font-bold uppercase tracking-[.08em] text-[#d2a8ff]">Pasar a entrevista</button>}{application.status === "Entrevista" && <><button onClick={() => updateApplication.mutate({ id: application.id, status: "Aprobada" })} className="focus-ring rounded-lg border border-[#456c30] bg-[#1a3119] px-3 py-2 text-[10px] font-bold uppercase tracking-[.08em] text-[#b9ff78]">Aprobar</button><button onClick={() => updateApplication.mutate({ id: application.id, status: "Rechazada" })} className="focus-ring rounded-lg border border-[#74303b] bg-[#35171f] px-3 py-2 text-[10px] font-bold uppercase tracking-[.08em] text-[#ff8994]">Rechazar</button></>}{application.status === "Aprobada" && <button onClick={() => recruitApplication(application)} className="focus-ring rounded-lg border border-[#456c30] bg-[#1a3119] px-3 py-2 text-[10px] font-bold uppercase tracking-[.08em] text-[#b9ff78]">Añadir a tryout</button>}</div></div></div>)}</div></div><div className="panel mb-4 overflow-hidden"><div className="hidden grid-cols-[1.35fr_1fr_1fr_1fr_110px] gap-4 border-b border-[#202e3e] px-5 py-3 md:grid"><div className="eyebrow">Jugador</div><div className="eyebrow">Rol</div><div className="eyebrow">Rango</div><div className="eyebrow">Fuente</div><div className="eyebrow">Estado</div></div><div className="divide-y divide-[#1c2938]">{filteredPlayers.length ? filteredPlayers.map((player) => <div key={player.id} className="grid gap-3 px-4 py-4 transition hover:bg-[#111a25] md:grid-cols-[1.35fr_1fr_1fr_1fr_110px] md:items-center md:gap-4 md:px-5"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-lg font-display text-lg font-bold" style={{ color: player.color, backgroundColor: `${player.color}16` }}>{player.handle.charAt(0)}</span><div><div className="text-sm font-bold text-white">{player.handle}</div><div className="mt-1 text-xs text-[#cbd5e0] md:hidden">{player.role} · {player.rank} · {player.source}</div></div></div><div className="hidden text-sm font-medium text-[#d2dce7] md:block">{player.role}</div><div className="hidden text-sm font-medium text-[#d2dce7] md:block">{player.rank}</div><div className="hidden text-sm md:block"><Badge tone={player.source === "Tracker.gg" ? "blue" : player.source === "TPG" ? "orange" : player.source === "Discord" ? "purple" : "slate"}>{player.source}</Badge></div><div><Badge tone={player.status === "Activo" ? "green" : player.status === "Tryout" ? "purple" : player.status === "Pendiente" ? "orange" : "slate"}>{player.status}</Badge></div></div>) : <div className="p-8 text-center text-sm text-[#c1ccda]">No hay jugadores que coincidan con los filtros actuales.</div>}</div></div><div className="mt-4 panel flex flex-col gap-4 p-5 md:flex-row md:items-center md:justify-between"><div><div className="eyebrow mb-2 text-[#ffad69]">Regla de ingreso CROSAIM</div><p className="text-sm leading-6 text-[#cbd5e0]">Mentalidad competitiva, comunicación efectiva, compromiso con el entrenamiento y disponibilidad para torneos. La actitud también entra en el roster.</p></div><a href={tpgRegisterUrl} target="_blank" rel="noreferrer" className="focus-ring inline-flex shrink-0 items-center justify-center gap-2 rounded-lg border border-[#704523] bg-[#2b1b10] px-4 py-2.5 text-xs font-bold uppercase tracking-[.1em] text-[#ffad69] hover:bg-[#3a2414]">Registrar perfil TPG <ExternalLink className="h-3.5 w-3.5" /></a></div></>;
}
function FilterSelect({ label, value, options, onChange }: { label: string; value: string; options: string[]; onChange: (value: string) => void }) { return <label className="relative"><span className="sr-only">{label}</span><select value={value} onChange={(event) => onChange(event.target.value)} className="focus-ring w-full appearance-none rounded-lg border border-[#2c3c50] bg-[#0a1018] px-3 py-2.5 text-xs text-white"><option value="Todos">Todos los {label.toLowerCase()}s</option>{options.filter((option) => option !== "Todos").map((option) => <option key={option}>{option}</option>)}</select></label>; }

function Tournaments() { const [registered, setRegistered] = useState<string[]>([]); return <><SectionHeader eyebrow="Competición · TPG" title="Torneos & calendario" description="Planifica la ruta competitiva de CROSAIM: registro, preparación, participación y seguimiento. Los enlaces llevan al registro oficial de TPG." action={<a href={tpgUrl} target="_blank" rel="noreferrer" className="focus-ring inline-flex items-center justify-center gap-2 rounded-lg border border-[#704523] bg-[#2b1b10] px-4 py-2.5 text-xs font-bold uppercase tracking-[.12em] text-[#ffad69] hover:bg-[#3a2414]">Abrir TPG <ExternalLink className="h-4 w-4" /></a>} /><div className="panel mb-4 overflow-hidden"><div className="border-b border-[#253346] bg-[#121c28] px-5 py-4"><div className="flex items-center gap-2"><Trophy className="h-4 w-4 text-[#ff7a18]" /><span className="text-sm font-bold text-white">Ruta CROSAIM · Temporada 2026</span><Badge tone="orange">3 paradas</Badge></div></div><div className="grid divide-y divide-[#1e2b3b] md:grid-cols-3 md:divide-x md:divide-y-0">{tournamentData.map((item, index) => { const isRegistered = registered.includes(item.name); return <div key={item.name} className="p-5"><div className="mb-8 flex items-start justify-between"><div><span className="eyebrow">0{index + 1} / parada</span><h2 className="mt-2 font-display text-3xl font-bold uppercase text-white">{item.name.replace("TPG ", "")}</h2></div><span className="h-3 w-3 rounded-full" style={{ backgroundColor: item.color, boxShadow: `0 0 0 5px ${item.color}20` }} /></div><div className="font-display text-2xl font-bold text-[#dce6ef]">{item.date}</div><div className="mt-1 text-xs text-[#8190a3]">{item.city}</div><div className="mt-6 flex items-center justify-between gap-3"><Badge tone={index === 0 ? "red" : index === 1 ? "orange" : "slate"}>{item.state}</Badge><button onClick={() => setRegistered((current) => isRegistered ? current.filter((name) => name !== item.name) : [...current, item.name])} className={classNames("focus-ring rounded-lg px-3 py-2 text-[10px] font-bold uppercase tracking-[.1em] transition", isRegistered ? "border border-[#456c30] bg-[#1a3119] text-[#b9ff78]" : "border border-[#2c3d52] bg-[#172231] text-[#b9c8d7] hover:border-[#5a7597] hover:text-white")}>{isRegistered ? <><Check className="mr-1 inline h-3.5 w-3.5" /> En seguimiento</> : "Seguir parada"}</button></div><a href={item.url} target="_blank" rel="noreferrer" className="mt-4 inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-[.1em] text-[#71849a] hover:text-white">Ver información oficial <ArrowUpRight className="h-3 w-3" /></a></div>; })}</div></div><div className="grid gap-4 lg:grid-cols-2"><div className="panel p-5 md:p-6"><div className="eyebrow mb-2">Proceso de participación</div><h2 className="font-display text-2xl font-bold uppercase text-white">De perfil a playoffs</h2><div className="mt-6 grid gap-3 sm:grid-cols-2">{[{ icon: UserPlus, n: "01", t: "Registrar", d: "Crea el perfil gamer y completa los datos." }, { icon: Swords, n: "02", t: "Jugar retos", d: "Suma victorias y sube en el ranking." }, { icon: BarChart3, n: "03", t: "Dar seguimiento", d: "Registra resultados y puntos de cada jugador." }, { icon: Trophy, n: "04", t: "Clasificar", d: "Los mejores avanzan a playoffs y premios." }].map((item) => <div key={item.n} className="rounded-xl border border-[#233144] bg-[#0c131c] p-4"><div className="flex items-center justify-between"><span className="font-display text-2xl font-bold text-[#3c4c61]">{item.n}</span><item.icon className="h-4 w-4 text-[#ff7a18]" /></div><div className="mt-3 text-sm font-bold text-white">{item.t}</div><div className="mt-1 text-xs leading-5 text-[#7f8ea1]">{item.d}</div></div>)}</div></div><div className="panel p-5 md:p-6"><div className="eyebrow mb-2">Control de acceso</div><h2 className="font-display text-2xl font-bold uppercase text-white">Qué falta conectar</h2><div className="mt-5 space-y-3"><CheckLine label="Calendario público TPG" done /><CheckLine label="Enlace de registro de jugadores" done /><CheckLine label="Resultados de retos y ranking" /><CheckLine label="Cuenta administradora CROSAIM" /></div><p className="mt-5 border-t border-[#202e40] pt-4 text-xs leading-5 text-[#7b8b9e]">La integración oficial de datos depende de que TPG habilite una cuenta, API o exportación. Este panel mantiene el control operativo y enlaza cada paso con la fuente oficial.</p></div></div></>; }
function CheckLine({ label, done = false }: { label: string; done?: boolean }) { return <div className="flex items-center gap-3 text-sm text-[#c4ceda]"><span className={classNames("flex h-5 w-5 items-center justify-center rounded-full border", done ? "border-[#456c30] bg-[#203a1e] text-[#b9ff78]" : "border-[#37485e] text-[#65758a]")}>{done ? <Check className="h-3 w-3" /> : <span className="h-1.5 w-1.5 rounded-full bg-[#65758a]" />}</span>{label}</div>; }

function ClipLibrary({ clips, setClips }: { clips: ClipItem[]; setClips: React.Dispatch<React.SetStateAction<ClipItem[]>> }) {
  const { user } = useAuth(); const createClip = trpc.clips.create.useMutation(); const inputRef = useRef<HTMLInputElement>(null); const [uploading, setUploading] = useState(false); const [uploadError, setUploadError] = useState("");
  const uploadClip = async (file: File) => { if (file.size > 120 * 1024 * 1024) { setUploadError("El clip supera el límite de 120 MB."); return; } const allowedTypes = ["video/mp4", "video/webm", "video/quicktime", "video/x-matroska"]; if (!allowedTypes.includes(file.type)) { setUploadError("Formato no permitido. Usa MP4, WebM, MOV o MKV."); return; } setUploading(true); setUploadError(""); try { const response = await fetch("/api/clips/upload", { method: "POST", headers: { "Content-Type": file.type, "X-File-Name": encodeURIComponent(file.name) }, body: file }); if (!response.ok) throw new Error("upload-failed"); const payload = await response.json() as { url: string; name: string; size: number; contentType: string }; const clip = { name: payload.name, url: payload.url, size: payload.size, contentType: payload.contentType, status: "Subido" as const }; setClips((items) => [{ id: Date.now(), ...clip, uploadedAt: new Date().toISOString() }, ...items]); if (user) createClip.mutate(clip); } catch { const localUrl = URL.createObjectURL(file); setClips((items) => [{ id: Date.now(), name: file.name, url: localUrl, size: file.size, contentType: file.type, uploadedAt: new Date().toISOString(), status: "Vista previa local" }, ...items]); setUploadError("No se pudo guardar en almacenamiento; se dejó una vista previa local en este navegador."); } finally { setUploading(false); } };
  return <div className="panel mb-4 p-5 md:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><div className="eyebrow mb-2">Biblioteca de clips</div><h2 className="font-display text-2xl font-bold uppercase text-white">Sube el material del equipo</h2><p className="mt-2 max-w-xl text-xs leading-5 text-[#8493a6]">Acepta videos para convertirlos en guías de 5–15 segundos, revisarlos y programarlos en el calendario de Tracker.gg.</p></div><button onClick={() => inputRef.current?.click()} disabled={uploading} className="focus-ring inline-flex items-center justify-center gap-2 rounded-lg border border-[#24528f] bg-[#102640] px-4 py-2.5 text-xs font-bold uppercase tracking-[.1em] text-[#73b2ff] hover:bg-[#153452] disabled:opacity-50"><Upload className="h-4 w-4" /> {uploading ? "Subiendo..." : "Subir clip"}</button><input ref={inputRef} type="file" accept="video/*" className="hidden" onChange={(event) => { const file = event.target.files?.[0]; if (file) void uploadClip(file); event.target.value = ""; }} /></div>{uploadError && <div className="mt-3 rounded-lg border border-[#714521] bg-[#301d11] px-3 py-2 text-xs text-[#ffad69]">{uploadError}</div>}<div className="mt-5 grid gap-2 sm:grid-cols-2">{clips.length ? clips.slice(0, 4).map((clip) => <div key={clip.id} className="flex items-center gap-3 rounded-xl border border-[#223246] bg-[#0b121a] p-3"><video src={clip.url} muted preload="metadata" className="h-12 w-16 rounded-lg bg-black object-cover" /><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold text-white">{clip.name}</div><div className="mt-1 text-[10px] text-[#7f8ea1]">{formatBytes(clip.size)} · {clip.status}</div></div><a href={clip.url} target="_blank" rel="noreferrer" className="text-[#71849a] hover:text-white" aria-label={`Abrir ${clip.name}`}><Play className="h-4 w-4" /></a></div>) : <div className="rounded-xl border border-dashed border-[#2b3d53] px-4 py-5 text-center text-xs text-[#718198] sm:col-span-2">Todavía no hay clips cargados. Empieza por una jugada táctica clara.</div>}</div></div>;
}

function ContentBoard({ content, setContent, clips, setClips, setSection }: { content: ContentItem[]; setContent: React.Dispatch<React.SetStateAction<ContentItem[]>>; clips: ClipItem[]; setClips: React.Dispatch<React.SetStateAction<ClipItem[]>>; setSection: (section: Section) => void }) {
  const { user } = useAuth(); const createContentItem = trpc.content.create.useMutation(); const [activeTab, setActiveTab] = useState<"all" | ContentPlatform>("all"); const [showForm, setShowForm] = useState(false); const [newTitle, setNewTitle] = useState(""); const [copied, setCopied] = useState<number | null>(null); const filtered = activeTab === "all" ? content : content.filter((item) => item.platform === activeTab);
  const copyBrief = async (item: ContentItem) => { try { await navigator.clipboard.writeText(`${item.title}\n${item.description}\n\nCROSAIM · Competimos con propósito.`); } catch {} setCopied(item.id); window.setTimeout(() => setCopied(null), 1800); };
  const addContent = () => { if (!newTitle.trim()) return; const item = { title: newTitle.trim(), type: "Nueva pieza · por definir", platform: "Tracker.gg" as const, status: "Borrador" as const, accent: "#1677ff", description: "Añade aquí el mapa, agente, fase y aprendizaje principal." }; setContent((items) => [{ id: Date.now(), ...item }, ...items]); if (user) createContentItem.mutate(item); setNewTitle(""); setShowForm(false); };
  return <><SectionHeader eyebrow="Contenido · descubrimiento" title="Contenido Tracker" description="Convierte el conocimiento del equipo en clips tácticos cortos, claros y publicables. Sube videos, prepara el brief y programa la salida desde el calendario." action={<div className="flex flex-wrap gap-2"><button onClick={() => setSection("calendar")} className="focus-ring inline-flex items-center justify-center gap-2 rounded-lg border border-[#2c3d52] bg-[#121c28] px-4 py-2.5 text-xs font-bold uppercase tracking-[.1em] text-[#b8c5d3] hover:text-white"><CalendarDays className="h-4 w-4" /> Calendario</button><button onClick={() => setShowForm((value) => !value)} className="focus-ring inline-flex items-center justify-center gap-2 rounded-lg bg-[#1677ff] px-4 py-2.5 text-xs font-bold uppercase tracking-[.1em] text-white transition hover:bg-[#2e87ff]"><Plus className="h-4 w-4" /> Nueva pieza</button></div>} /><ClipLibrary clips={clips} setClips={setClips} /><div className="panel mb-4 flex flex-col gap-4 p-4 md:flex-row md:items-center md:justify-between"><div className="flex flex-wrap gap-2">{(["all", "Tracker.gg", "TikTok / Reels", "Discord"] as const).map((tab) => <button key={tab} onClick={() => setActiveTab(tab)} className={classNames("focus-ring rounded-lg px-3 py-2 text-[10px] font-bold uppercase tracking-[.1em] transition", activeTab === tab ? "bg-[#e8eef5] text-[#0c131c]" : "border border-[#2a3a4e] text-[#8fa0b3] hover:text-white")}>{tab === "all" ? "Todo el pipeline" : tab}</button>)}</div><a href={trackerUrl} target="_blank" rel="noreferrer" className="focus-ring inline-flex items-center gap-2 text-xs font-bold uppercase tracking-[.1em] text-[#7cb7ff] hover:text-white">Abrir guías de Tracker <ExternalLink className="h-3.5 w-3.5" /></a></div>{showForm && <div className="panel mb-4 flex flex-col gap-3 p-4 md:flex-row md:items-end"><label className="flex-1"><span className="eyebrow mb-2 block">Título de la pieza</span><input value={newTitle} onChange={(event) => setNewTitle(event.target.value)} placeholder="Ej. Sova · dart para limpiar A main" className="focus-ring w-full rounded-lg border border-[#2c3c50] bg-[#0a1018] px-3 py-2.5 text-sm text-white placeholder:text-[#637287]" /></label><button onClick={addContent} className="focus-ring rounded-lg border border-[#24528f] bg-[#102640] px-4 py-2.5 text-xs font-bold uppercase tracking-[.1em] text-[#73b2ff] hover:bg-[#153452]">Añadir al pipeline</button></div>}<div className="grid gap-4 lg:grid-cols-[1.3fr_.7fr]"><div className="panel overflow-hidden"><div className="border-b border-[#202e3e] px-5 py-4"><div className="flex items-center justify-between"><div><div className="eyebrow mb-2">{filtered.length} piezas visibles</div><h2 className="font-display text-2xl font-bold uppercase text-white">Tablero de publicación</h2></div><FileText className="h-5 w-5 text-[#718198]" /></div></div><div className="divide-y divide-[#1c2938]">{filtered.map((item) => <div key={item.id} className="p-4 transition hover:bg-[#111a25] md:p-5"><div className="flex items-start gap-3"><span className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg" style={{ color: item.accent, backgroundColor: `${item.accent}18` }}>{item.platform === "Tracker.gg" ? <Target className="h-4 w-4" /> : <Video className="h-4 w-4" />}</span><div className="min-w-0 flex-1"><div className="flex flex-col justify-between gap-2 sm:flex-row sm:items-start"><div><h3 className="text-sm font-bold text-white">{item.title}</h3><div className="mt-1 text-xs text-[#7d8ca0]">{item.type} · {item.platform}</div></div><Badge tone={item.status === "Publicado" ? "green" : item.status === "Listo para publicar" ? "blue" : "slate"}>{item.status}</Badge></div><p className="mt-3 text-xs leading-5 text-[#8998aa]">{item.description}</p><div className="mt-4 flex flex-wrap gap-2"><button onClick={() => copyBrief(item)} className="focus-ring inline-flex items-center gap-1.5 rounded-md border border-[#2b3b50] px-2.5 py-1.5 text-[10px] font-bold uppercase tracking-[.08em] text-[#a1afbf] hover:text-white">{copied === item.id ? <Check className="h-3 w-3 text-[#b9ff78]" /> : <Link2 className="h-3 w-3" />} {copied === item.id ? "Copiado" : "Copiar brief"}</button>{item.platform === "Tracker.gg" && <><button onClick={() => setSection("calendar")} className="focus-ring inline-flex items-center gap-1.5 rounded-md border border-[#2c3d52] bg-[#121c28] px-2.5 py-1.5 text-[10px] font-bold uppercase tracking-[.08em] text-[#b7c5d3] hover:text-white"><CalendarPlus className="h-3 w-3" /> Programar</button><a href={trackerUrl} target="_blank" rel="noreferrer" className="focus-ring inline-flex items-center gap-1.5 rounded-md border border-[#24528f] bg-[#102640] px-2.5 py-1.5 text-[10px] font-bold uppercase tracking-[.08em] text-[#73b2ff] hover:bg-[#153452]">Enviar a Tracker <ExternalLink className="h-3 w-3" /></a></>}</div></div></div></div>)}</div></div><div className="space-y-4"><div className="panel p-5"><div className="eyebrow mb-2">Receta Tracker.gg</div><h2 className="font-display text-2xl font-bold uppercase text-white">Una guía que sí se ve</h2><div className="mt-5 space-y-3"><Step n="01" title="5–15 segundos" detail="Muestra el resultado sin introducciones largas." /><Step n="02" title="Agente + mapa" detail="Da contexto para que la guía sea filtrable." /><Step n="03" title="Un objetivo" detail="Un lineup, una entrada o una decisión." /><Step n="04" title="Aprendizaje" detail="Titula con claridad y explica el uso." /></div><a href={trackerUrl} target="_blank" rel="noreferrer" className="focus-ring mt-5 flex items-center justify-center gap-2 border-t border-[#202e40] pt-4 text-xs font-bold uppercase tracking-[.1em] text-[#7cb7ff] hover:text-white">Ver ejemplos de la comunidad <ArrowUpRight className="h-3.5 w-3.5" /></a></div><div className="panel p-5"><div className="eyebrow mb-2">Estado de biblioteca</div><h2 className="font-display text-2xl font-bold uppercase text-white">{clips.length} clips cargados</h2><p className="mt-2 text-xs leading-5 text-[#7f8ea1]">Los videos subidos quedan disponibles en el almacenamiento del proyecto; los previews locales se mantienen solo en este navegador.</p></div></div></div></>;
}
function Step({ n, title, detail }: { n: string; title: string; detail: string }) { return <div className="flex gap-3"><span className="font-display text-lg font-bold text-[#3b4c61]">{n}</span><div><div className="text-sm font-bold text-[#dce5ed]">{title}</div><p className="mt-1 text-xs leading-5 text-[#7f8ea1]">{detail}</p></div></div>; }

function CalendarSection({ schedule, setSchedule }: { schedule: ScheduleItem[]; setSchedule: React.Dispatch<React.SetStateAction<ScheduleItem[]>> }) {
  const { user } = useAuth(); const createScheduleItem = trpc.calendar.create.useMutation(); const [month, setMonth] = useState(() => new Date(2026, 8, 1)); const [selected, setSelected] = useState("2026-09-08"); const [showForm, setShowForm] = useState(false); const [title, setTitle] = useState(""); const [time, setTime] = useState("19:00"); const [platform, setPlatform] = useState<ContentPlatform>("Tracker.gg");
  const year = month.getFullYear(); const monthIndex = month.getMonth(); const firstDay = (new Date(year, monthIndex, 1).getDay() + 6) % 7; const days = new Date(year, monthIndex + 1, 0).getDate(); const cells = Array.from({ length: Math.ceil((firstDay + days) / 7) * 7 }, (_, index) => { const day = index - firstDay + 1; return day > 0 && day <= days ? new Date(year, monthIndex, day) : null; }); const selectedEvents = schedule.filter((item) => item.date === selected);
  const addSchedule = () => { if (!title.trim()) return; const item = { date: selected, time, title: title.trim(), platform, status: "Planificada" as const }; setSchedule((items) => [...items, { id: Date.now(), ...item }]); if (user) createScheduleItem.mutate(item); setTitle(""); setShowForm(false); };
  return <><SectionHeader eyebrow="Contenido · programación" title="Calendario editorial" description="Programa cuándo sale cada pieza de Tracker.gg, TikTok/Reels o Discord. Cambia de mes, selecciona un día y deja la publicación lista para ejecutar." action={<button onClick={() => setShowForm((value) => !value)} className="focus-ring inline-flex items-center justify-center gap-2 rounded-lg bg-[#e6293f] px-4 py-2.5 text-xs font-bold uppercase tracking-[.12em] text-white hover:bg-[#f04153]"><CalendarPlus className="h-4 w-4" /> Programar publicación</button>} /><div className="grid gap-4 xl:grid-cols-[1.2fr_.8fr]"><div className="panel overflow-hidden"><div className="flex items-center justify-between border-b border-[#202e40] px-5 py-4"><div><div className="eyebrow mb-2">{new Intl.DateTimeFormat("es-VE", { month: "long", year: "numeric" }).format(month)}</div><h2 className="font-display text-2xl font-bold uppercase text-white">Plan de publicaciones</h2></div><div className="flex gap-2"><IconButton label="Mes anterior" onClick={() => setMonth(new Date(year, monthIndex - 1, 1))}><ChevronLeft className="h-4 w-4" /></IconButton><IconButton label="Mes siguiente" onClick={() => setMonth(new Date(year, monthIndex + 1, 1))}><ChevronRight className="h-4 w-4" /></IconButton></div></div><div className="grid grid-cols-7 border-b border-[#202e40]">{["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"].map((day) => <div key={day} className="py-3 text-center text-[10px] font-bold uppercase tracking-[.12em] text-[#68798e]">{day}</div>)}</div><div className="grid grid-cols-7">{cells.map((cell, index) => { const key = cell ? dateKey(cell) : `empty-${index}`; const events = cell ? schedule.filter((item) => item.date === key) : []; const isSelected = key === selected; return <button key={key} disabled={!cell} onClick={() => cell && setSelected(key)} className={classNames("min-h-[92px] border-b border-r border-[#1a2838] p-2 text-left transition last:border-r-0", cell ? "hover:bg-[#111c28]" : "bg-[#090e14]", isSelected && "bg-[#1b1218] ring-1 ring-inset ring-[#e6293f]")}><div className={classNames("flex h-6 w-6 items-center justify-center rounded-full font-display text-sm font-bold", isSelected ? "bg-[#e6293f] text-white" : cell ? "text-[#aab8c8]" : "text-transparent")}>{cell?.getDate() ?? "0"}</div><div className="mt-2 space-y-1">{events.slice(0, 2).map((event) => <div key={event.id} className={classNames("truncate rounded px-1.5 py-1 text-[9px] font-bold", event.platform === "Tracker.gg" ? "bg-[#102640] text-[#73b2ff]" : event.platform === "Discord" ? "bg-[#241633] text-[#d2a8ff]" : "bg-[#35171f] text-[#ff8994]")}>{event.time} · {event.title}</div>)}{events.length > 2 && <div className="text-[9px] text-[#708198]">+{events.length - 2} más</div>}</div></button>; })}</div></div><div className="space-y-4"><div className="panel p-5"><div className="eyebrow mb-2">Día seleccionado</div><h2 className="font-display text-3xl font-bold uppercase text-white">{humanDate(selected)}</h2><div className="mt-5 space-y-2">{selectedEvents.length ? selectedEvents.map((event) => <div key={event.id} className="rounded-xl border border-[#25364b] bg-[#0c131c] p-3"><div className="flex items-start justify-between gap-2"><div className="text-sm font-bold text-white">{event.title}</div><Badge tone={event.status === "Publicada" ? "green" : event.status === "Planificada" ? "blue" : "slate"}>{event.status}</Badge></div><div className="mt-2 text-xs text-[#7f8ea1]">{event.time} · {event.platform}</div></div>) : <div className="rounded-xl border border-dashed border-[#2b3d53] px-4 py-8 text-center text-xs text-[#718198]">No hay publicaciones para este día.</div>}</div></div>{showForm && <div className="panel p-5"><div className="eyebrow mb-2">Nueva publicación</div><h2 className="font-display text-2xl font-bold uppercase text-white">Programar en {humanDate(selected)}</h2><div className="mt-4 space-y-3"><input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Título de la publicación" className="focus-ring w-full rounded-lg border border-[#2c3c50] bg-[#0a1018] px-3 py-2.5 text-sm text-white placeholder:text-[#637287]" /><div className="grid grid-cols-2 gap-2"><input type="time" value={time} onChange={(event) => setTime(event.target.value)} className="focus-ring rounded-lg border border-[#2c3c50] bg-[#0a1018] px-3 py-2.5 text-sm text-white" /><select value={platform} onChange={(event) => setPlatform(event.target.value as ContentPlatform)} className="focus-ring rounded-lg border border-[#2c3c50] bg-[#0a1018] px-3 py-2.5 text-xs text-white"><option>Tracker.gg</option><option>TikTok / Reels</option><option>Discord</option></select></div><button onClick={addSchedule} className="focus-ring w-full rounded-lg bg-[#e6293f] px-4 py-2.5 text-xs font-bold uppercase tracking-[.1em] text-white hover:bg-[#f04153]">Guardar en calendario</button></div></div>}<div className="panel p-5"><div className="eyebrow mb-2">Regla de ejecución</div><p className="text-sm leading-6 text-[#98a7b8]">El calendario organiza y prepara la publicación. El envío final a Tracker.gg sigue siendo manual porque la plataforma requiere la aprobación de sus guías comunitarias.</p></div></div></div></>;
}

function Analytics() { return <><SectionHeader eyebrow="Análisis · decisión" title="Estrategia & análisis" description="Tracker.gg funciona como canal de descubrimiento táctico y TPG como canal de competición. El centro propio coordina ambos sin fingir una integración de datos que aún requiere credenciales o API oficiales." action={<button onClick={() => window.print()} className="focus-ring inline-flex items-center justify-center gap-2 rounded-lg border border-[#2c3d52] bg-[#121c28] px-4 py-2.5 text-xs font-bold uppercase tracking-[.12em] text-[#b8c5d3] hover:text-white"><FileText className="h-4 w-4" /> Exportar vista</button>} /><div className="grid gap-4 lg:grid-cols-2"><div className="panel p-5 md:p-6"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#102640] text-[#73b2ff]"><Target className="h-5 w-5" /></span><div><div className="eyebrow">Canal 01 · alcance</div><h2 className="font-display text-2xl font-bold uppercase text-white">Tracker.gg</h2></div></div><p className="mt-5 text-sm leading-6 text-[#a5b1c0]">La página de guías de Valorant está orientada a clips de 5–15 segundos enviados por la comunidad. Permite filtrar por agente, mapa y objetivo, y las guías pasan por una aprobación rápida antes de distribuirse.</p><div className="mt-5 space-y-3"><CheckLine label="Publicar conocimiento táctico" done /><CheckLine label="Asociar agente, mapa y objetivo" done /><CheckLine label="Construir autoridad del equipo" done /><CheckLine label="Métricas propias de CROSAIM" /></div><a href={trackerUrl} target="_blank" rel="noreferrer" className="focus-ring mt-6 flex items-center justify-center gap-2 rounded-lg border border-[#24528f] bg-[#102640] px-4 py-3 text-xs font-bold uppercase tracking-[.1em] text-[#73b2ff] hover:bg-[#153452]">Ir a guías de Valorant <ExternalLink className="h-4 w-4" /></a></div><div className="panel p-5 md:p-6"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#2b1b10] text-[#ffad69]"><Trophy className="h-5 w-5" /></span><div><div className="eyebrow">Canal 02 · competición</div><h2 className="font-display text-2xl font-bold uppercase text-white">Torneos Pro Gamers</h2></div></div><p className="mt-5 text-sm leading-6 text-[#a5b1c0]">TPG ofrece registro gratuito, retos, ranking, clasificación a playoffs, torneos presenciales y membresías. Es el lugar para convertir la preparación del roster en experiencia competitiva medible.</p><div className="mt-5 space-y-3"><CheckLine label="Crear perfil gamer" done /><CheckLine label="Jugar retos y subir ranking" done /><CheckLine label="Clasificar a playoffs" done /><CheckLine label="Resultados automáticos en CROSAIM" /></div><a href={tpgRegisterUrl} target="_blank" rel="noreferrer" className="focus-ring mt-6 flex items-center justify-center gap-2 rounded-lg border border-[#704523] bg-[#2b1b10] px-4 py-3 text-xs font-bold uppercase tracking-[.1em] text-[#ffad69] hover:bg-[#3a2414]">Abrir registro oficial <ExternalLink className="h-4 w-4" /></a></div></div><div className="panel mt-4 p-5 md:p-6"><div className="eyebrow mb-2">Recomendación de operación</div><h2 className="font-display text-3xl font-bold uppercase text-white">Un embudo, tres momentos</h2><div className="mt-6 grid gap-3 md:grid-cols-3">{[{ n: "01", title: "Descubrir", c: "#1677ff", icon: Search, detail: "Publica guías cortas, limpias y útiles para que jugadores de Valorant conozcan el criterio de CROSAIM." }, { n: "02", title: "Confiar", c: "#9b3dff", icon: Shield, detail: "Repite una identidad visual, comparte análisis y demuestra disciplina en cada publicación." }, { n: "03", title: "Competir", c: "#e6293f", icon: Trophy, detail: "Lleva al roster a TPG, registra los hitos y convierte la participación en historial competitivo." }].map((item) => <div key={item.n} className="relative overflow-hidden rounded-xl border border-[#243347] bg-[#0c131c] p-5"><span className="font-display text-5xl font-bold" style={{ color: `${item.c}42` }}>{item.n}</span><item.icon className="absolute right-5 top-5 h-5 w-5" style={{ color: item.c }} /><h3 className="mt-4 font-display text-2xl font-bold uppercase text-white">{item.title}</h3><p className="mt-2 text-xs leading-5 text-[#8493a6]">{item.detail}</p></div>)}</div></div></>; }
function SmallMetric({ label, value, note, color }: { label: string; value: string; note: string; color: string }) { return <div className="panel p-4"><div className="eyebrow">{label}</div><div className="mt-3 font-display text-3xl font-bold text-white">{value}</div><div className="mt-1 text-xs" style={{ color }}>{note}</div></div>; }

export default function Home() {
  const { user } = useAuth(); const [section, setSection] = useState<Section>("overview"); const [mobileNav, setMobileNav] = useState(false);
  const notificationUtils = trpc.useUtils();
  const rosterQuery = trpc.roster.list.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const contentQuery = trpc.content.list.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const calendarQuery = trpc.calendar.list.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const clipsQuery = trpc.clips.list.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const workspaceImport = trpc.workspace.importLocal.useMutation();
  const serverNotificationsQuery = trpc.notifications.list.useQuery(undefined, { enabled: Boolean(user), retry: false, refetchInterval: user ? 30000 : false });
  const createNotificationMutation = trpc.notifications.create.useMutation({ onSuccess: () => void notificationUtils.notifications.list.invalidate() });
  const markNotificationMutation = trpc.notifications.markRead.useMutation({ onSuccess: () => void notificationUtils.notifications.list.invalidate() });
  const dismissNotificationMutation = trpc.notifications.dismiss.useMutation({ onSuccess: () => void notificationUtils.notifications.list.invalidate() });
  const savePushSubscriptionMutation = trpc.notifications.subscribePush.useMutation();
  const [players, setPlayers] = useState<Player[]>(() => { try { const stored = localStorage.getItem("crosaim-players"); return stored ? JSON.parse(stored) : initialPlayers; } catch { return initialPlayers; } });
  const [content, setContent] = useState<ContentItem[]>(() => { try { const stored = localStorage.getItem("crosaim-content"); return stored ? JSON.parse(stored) : initialContent; } catch { return initialContent; } });
  const [clips, setClips] = useState<ClipItem[]>(() => { try { const stored = localStorage.getItem("crosaim-clips"); return stored ? JSON.parse(stored) : []; } catch { return []; } });
  const [schedule, setSchedule] = useState<ScheduleItem[]>(() => { try { const stored = localStorage.getItem("crosaim-schedule"); return stored ? JSON.parse(stored) : initialSchedule; } catch { return initialSchedule; } });
  const [notifications, setNotifications] = useState<NotificationItem[]>(initialNotifications);
  const [customNotifications, setCustomNotifications] = useState<CustomNotification[]>(() => { try { const stored = localStorage.getItem("crosaim-custom-notifications"); return stored ? JSON.parse(stored) : initialCustomNotifications; } catch { return initialCustomNotifications; } });
  const [discordData, setDiscordData] = useState<DiscordWidgetData | null>(null);
  const lastUrgentAlertId = useRef<number | null>(null);
  const workspaceHydratedUser = useRef<string | null>(null);
  const serverCustomNotifications: CustomNotification[] = (serverNotificationsQuery.data ?? []).map((item) => ({ id: item.id, title: item.title, detail: item.detail, severity: item.severity, read: item.read, time: new Date(item.createdAt).toLocaleString("es-VE", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }) }));
  const displayedCustomNotifications = user && serverNotificationsQuery.data ? serverCustomNotifications : customNotifications;
  useEffect(() => { localStorage.setItem("crosaim-players", JSON.stringify(players)); }, [players]); useEffect(() => { localStorage.setItem("crosaim-content", JSON.stringify(content)); }, [content]); useEffect(() => { localStorage.setItem("crosaim-clips", JSON.stringify(clips.filter((clip) => clip.status === "Subido"))); }, [clips]); useEffect(() => { localStorage.setItem("crosaim-schedule", JSON.stringify(schedule)); }, [schedule]); useEffect(() => { localStorage.setItem("crosaim-custom-notifications", JSON.stringify(customNotifications)); }, [customNotifications]);
  useEffect(() => { if (!user || workspaceHydratedUser.current === user.openId || !rosterQuery.data || !contentQuery.data || !calendarQuery.data || !clipsQuery.data) return; workspaceHydratedUser.current = user.openId; const localMigrationAttempted = localStorage.getItem("crosaim-workspace-migration-attempted") === "1"; const hasServerData = rosterQuery.data.length + contentQuery.data.length + calendarQuery.data.length + clipsQuery.data.length > 0; if (hasServerData || localMigrationAttempted) { if (rosterQuery.data.length) setPlayers(rosterQuery.data.map((item) => ({ id: item.id, handle: item.handle, role: item.role, rank: item.rank, availability: item.availability, status: item.status, source: item.source, color: item.color }))); if (contentQuery.data.length) setContent(contentQuery.data.map((item) => ({ id: item.id, title: item.title, type: item.type, platform: item.platform, status: item.status, accent: item.accent, description: item.description }))); if (calendarQuery.data.length) setSchedule(calendarQuery.data.map((item) => ({ id: item.id, date: item.date, time: item.time, title: item.title, platform: item.platform, status: item.status }))); if (clipsQuery.data.length) setClips(clipsQuery.data.map((item) => ({ id: item.id, name: item.name, url: item.url, size: item.size, contentType: item.contentType, uploadedAt: new Date(item.uploadedAt).toISOString(), status: item.status }))); return; } const persistentClips = clips.filter((clip) => clip.status === "Subido" && clip.url.startsWith("/manus-storage/")); workspaceImport.mutate({ roster: players.map(({ id: _id, ...item }) => item), content: content.map(({ id: _id, ...item }) => item), calendar: schedule.map(({ id: _id, ...item }) => item), clips: persistentClips.map(({ id: _id, ...item }) => item) }, { onSettled: () => { localStorage.setItem("crosaim-workspace-migration-attempted", "1"); void rosterQuery.refetch(); void contentQuery.refetch(); void calendarQuery.refetch(); void clipsQuery.refetch(); } }); }, [user, rosterQuery.data, contentQuery.data, calendarQuery.data, clipsQuery.data]);
  useEffect(() => { let active = true; const refreshDiscord = async () => { try { const response = await fetch("/api/discord/widget"); if (!response.ok) return; const payload = await response.json() as DiscordWidgetData; if (active) setDiscordData(payload); } catch {} }; void refreshDiscord(); const timer = window.setInterval(() => void refreshDiscord(), 60000); return () => { active = false; window.clearInterval(timer); }; }, []);
  useEffect(() => { const urgent = displayedCustomNotifications.find((item) => item.severity === "urgent" && !item.read); if (!urgent) return; if (lastUrgentAlertId.current === null) { lastUrgentAlertId.current = urgent.id; return; } if (lastUrgentAlertId.current === urgent.id || typeof Notification === "undefined" || Notification.permission !== "granted") return; lastUrgentAlertId.current = urgent.id; void navigator.serviceWorker.ready.then((registration) => registration.showNotification(urgent.title, { body: urgent.detail, tag: `crosaim-${urgent.id}` })); }, [displayedCustomNotifications]);
  const activeLabel = useMemo(() => navItems.find((item) => item.id === section)?.label ?? "Resumen operativo", [section]);
  const sendTeamNotice = async (message: string) => { setNotifications((items) => [{ id: Date.now(), title: "Aviso enviado al equipo", detail: message, time: "Ahora", tone: "green" }, ...items]); if (user) createNotificationMutation.mutate({ title: "Aviso enviado al equipo", detail: message, severity: "info", source: "Discord" }); try { await fetch("/api/discord/notice", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message }) }); } catch {} };
  const enableBrowserAlerts = async () => { if (typeof Notification === "undefined") return; const permission = await Notification.requestPermission(); if (permission !== "granted") return; const registration = await navigator.serviceWorker.register("/sw.js"); const vapidPublicKey = (import.meta.env.VITE_VAPID_PUBLIC_KEY as string | undefined) ?? ""; if (user && vapidPublicKey && "PushManager" in window) { const existing = await registration.pushManager.getSubscription(); const normalizedKey = vapidPublicKey.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - (vapidPublicKey.length % 4)) % 4); const subscription = existing ?? await registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: Uint8Array.from(atob(normalizedKey), (char) => char.charCodeAt(0)) }); const json = subscription.toJSON(); if (json.endpoint && json.keys?.p256dh && json.keys.auth) savePushSubscriptionMutation.mutate({ endpoint: json.endpoint, p256dh: json.keys.p256dh, auth: json.keys.auth }); } };
  const addCustomNotification = (title: string, detail: string, severity: CustomNotification["severity"]) => { setCustomNotifications((items) => [{ id: Date.now(), title, detail, severity, read: false, time: "Ahora" }, ...items]); if (user) createNotificationMutation.mutate({ title, detail, severity }); };
  const markNotificationRead = (id: number) => { setCustomNotifications((items) => items.map((item) => item.id === id ? { ...item, read: !item.read } : item)); if (user && serverNotificationsQuery.data?.some((item) => item.id === id)) { const current = serverNotificationsQuery.data.find((item) => item.id === id); if (current) markNotificationMutation.mutate({ id, read: !current.read }); } };
  const dismissNotification = (id: number) => { setCustomNotifications((items) => items.filter((item) => item.id !== id)); if (user && serverNotificationsQuery.data?.some((item) => item.id === id)) dismissNotificationMutation.mutate({ id }); };
  return <div className="min-h-screen bg-[#070a0f] text-[#f2f6fa]"><aside className={classNames("fixed inset-y-0 left-0 z-40 w-[260px] border-r border-[#182536] bg-[#090d13] transition-transform duration-200 lg:translate-x-0", mobileNav ? "translate-x-0" : "-translate-x-full")}><div className="flex h-full flex-col"><div className="flex h-[86px] items-center justify-between border-b border-[#182536] px-5"><button onClick={() => setSection("overview")} className="focus-ring flex items-center gap-3 text-left"><span className="relative flex h-10 w-10 items-center justify-center overflow-hidden rounded-xl bg-[#e6293f] font-display text-2xl font-bold text-white"><span className="absolute -right-2 top-1 h-12 w-4 rotate-25 bg-white/20" />C</span><span><strong className="block font-display text-xl font-bold tracking-wide text-white">CROSAIM</strong><small className="eyebrow !text-[9px] !tracking-[.22em]">Control Center</small></span></button><button onClick={() => setMobileNav(false)} className="focus-ring rounded p-1 text-[#738197] hover:text-white lg:hidden"><X className="h-5 w-5" /></button></div><div className="flex-1 overflow-y-auto px-3 py-6"><div className="eyebrow mb-3 px-3">Operaciones</div><nav className="space-y-1">{navItems.filter((item) => item.id !== "admin" || user?.role === "admin").map((item) => <button key={item.id} onClick={() => { setSection(item.id); setMobileNav(false); }} className={classNames("focus-ring group flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-sm transition", section === item.id ? "bg-[#1a1117] text-white" : "text-[#8796a9] hover:bg-[#111923] hover:text-white")}><item.icon className={classNames("h-4 w-4", section === item.id ? "text-[#e6293f]" : "text-[#617186] group-hover:text-white")} /><span className="flex-1">{item.label}</span>{section === item.id && <span className="h-1.5 w-1.5 rounded-full bg-[#e6293f]" />}</button>)}</nav><div className="my-7 border-t border-[#182536]" /><div className="eyebrow mb-3 px-3">Accesos oficiales</div><a href={trackerUrl} target="_blank" rel="noreferrer" className="flex items-center gap-3 rounded-lg px-3 py-3 text-sm text-[#8796a9] transition hover:bg-[#111923] hover:text-white"><Target className="h-4 w-4 text-[#1677ff]" /><span className="flex-1">Tracker.gg</span><ExternalLink className="h-3.5 w-3.5 text-[#52647b]" /></a><a href={tpgUrl} target="_blank" rel="noreferrer" className="flex items-center gap-3 rounded-lg px-3 py-3 text-sm text-[#8796a9] transition hover:bg-[#111923] hover:text-white"><Trophy className="h-4 w-4 text-[#ff7a18]" /><span className="flex-1">Torneos Pro Gamers</span><ExternalLink className="h-3.5 w-3.5 text-[#52647b]" /></a><a href={discordWidgetUrl} target="_blank" rel="noreferrer" className="flex items-center gap-3 rounded-lg px-3 py-3 text-sm text-[#8796a9] transition hover:bg-[#111923] hover:text-white"><MessageSquare className="h-4 w-4 text-[#9b3dff]" /><span className="flex-1">Discord CROSAIM</span><ExternalLink className="h-3.5 w-3.5 text-[#52647b]" /></a></div><div className="border-t border-[#182536] p-4"><div className="mb-3 flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[#a8ff2a] shadow-[0_0_10px_#a8ff2a]" /><span className="text-xs font-semibold text-[#c3ceda]">Sistema operativo</span></div>{user ? <div className="flex items-center gap-2 rounded-lg bg-[#101821] p-2"><span className="flex h-7 w-7 items-center justify-center rounded-full bg-[#e6293f] text-xs font-bold text-white">{user.name?.charAt(0).toUpperCase() ?? "C"}</span><span className="truncate text-xs text-[#aab7c6]">{user.name}</span></div> : <button onClick={() => startLogin()} className="focus-ring w-full rounded-lg border border-[#2d4057] bg-[#121c28] px-3 py-2.5 text-[10px] font-bold uppercase tracking-[.12em] text-[#b8c7d8] hover:border-[#e6293f] hover:text-white">Conectar cuenta</button>}</div></div></aside>{mobileNav && <button aria-label="Cerrar navegación" onClick={() => setMobileNav(false)} className="fixed inset-0 z-30 bg-black/60 lg:hidden" />}<div className="lg:pl-[260px]"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-[#182536] bg-[#080c12]/90 px-4 backdrop-blur-md md:px-8"><div className="flex items-center gap-3"><button onClick={() => setMobileNav(true)} className="focus-ring rounded-lg border border-[#26364b] p-2 text-[#97a6b8] lg:hidden"><Menu className="h-5 w-5" /></button><div><div className="eyebrow hidden md:block">CROSAIM / {section === "overview" ? "CONTROL ROOM" : section.toUpperCase()}</div><div className="text-sm font-semibold text-white md:hidden">{activeLabel}</div></div></div><div className="flex items-center gap-2 md:gap-4"><div className="hidden items-center gap-2 text-xs text-[#7d8da1] md:flex"><Clock3 className="h-3.5 w-3.5" /> 08 SEP 2026 · VET</div><IconButton label="Buscar"><Search className="h-4 w-4" /></IconButton><IconButton label="Ayuda"><CircleHelp className="h-4 w-4" /></IconButton><button onClick={() => user ? undefined : startLogin()} className="focus-ring hidden items-center gap-2 rounded-lg border border-[#2a3a4e] bg-[#121b27] px-3 py-2 text-xs font-semibold text-[#b8c6d4] transition hover:border-[#536b89] hover:text-white sm:flex">{user ? <><span className="h-2 w-2 rounded-full bg-[#a8ff2a]" /> Cuenta conectada</> : <><Command className="h-3.5 w-3.5" /> Conectar</>}</button></div></header><main className="mx-auto max-w-[1500px] px-4 py-6 md:px-8 md:py-8">{section === "overview" && <Overview setSection={setSection} players={players} content={content} notifications={notifications} customNotifications={displayedCustomNotifications} discordData={discordData} onSendNotice={sendTeamNotice} onAddCustomNotification={addCustomNotification} onMarkNotificationRead={markNotificationRead} onDismissNotification={dismissNotification} onEnableAlerts={enableBrowserAlerts} />}{section === "roster" && <Roster players={players} setPlayers={setPlayers} />}{section === "tournaments" && <Tournaments />}{section === "content" && <ContentBoard content={content} setContent={setContent} clips={clips} setClips={setClips} setSection={setSection} />}{section === "calendar" && <CalendarSection schedule={schedule} setSchedule={setSchedule} />}{section === "analytics" && <Analytics />}{section === "admin" && user?.role === "admin" && <AdminPushPanel />}<footer className="mt-10 flex flex-col justify-between gap-2 border-t border-[#172434] pt-5 text-[10px] uppercase tracking-[.14em] text-[#54647a] md:flex-row"><span>CROSAIM / Operations Center · 2026</span><span>Construido para entrenar · analizar · competir</span></footer></main></div></div>;
}
